nodes=[dict(id='Q:IC20261012',type='question',status='bounded_retrospective_diagnostic_completed',label='Do fixed positional counterparts supply necessary red IRAC colour evidence?',text='Selected native magnitudes were already consumed before registration. Only a named published colour component is tested; no full classifier or physical validation.',sources=paths[:4]),dict(id='F:IC20261012:availability',type='finding',status='verified_insufficient_classification_inputs',label='Zero of three best counterparts has four-band photometric availability',metrics=dict(available=0,cases=3,missing_eight_micron_cases=3),text='Missing native 8-micron entries prevent the declared full Phase-I classification. Missing entries are not flux limits, physical nondetections or starless labels.',sources=[paths[1],paths[4],paths[5],paths[6]]),dict(id='F:IC20261012:colours',type='finding',status='verified_conditional_colour_diagnostic',label='Two counterpart colours remain below the named necessary cut within quoted-error sensitivity',metrics=dict(case_ids=[x['case_id'] for x in s['case_assessments']],colour_36_45=[x['colour_mag'] for x in colours],upper_three_quoted_error_sensitivity=[x['envelopes']['3'][1] for x in colours],cut_strictly_greater_than=.7,quoted_error_incompatible=2,unresolved=1,robust_red_support=0),text='This qualifies interpretation of the projected source, not the correct 21/21 geometry. Sensitivity envelopes are not confidence bounds or physical Class-I exclusions.',sources=[paths[1],paths[4],paths[5],paths[7]]),dict(id='C:IC20261012:scope',type='qualification',status='unmet_physical_validation',label='Clump proxy ranking and point-source evolutionary class are different targets',text='All four old methods already selected these clumps; scores/models are unchanged. A high chemistry-proxy clump rank is not youth probability for a nearby point source. No membership, starless clump, universal colour class or birth is established.',sources=[paths[1],paths[6],paths[7]])]
edges=[dict(source='Q:IC20261012',target='F:IC20261012:availability',relation='answered_by'),dict(source='Q:IC20261012',target='F:IC20261012:colours',relation='answered_by'),dict(source='F:IC20261012:colours',target='F:NG20261012:alignment',relation='qualifies',text='Tight geometry remains valid while youth is unsupported by this named colour component.'),dict(source='C:IC20261012:scope',target='F:IC20261012:colours',relation='limits'),dict(source='C:IC20261012:scope',target='F:IC20261012:availability',relation='limits')]
