record=dict(schema='reviewed-irac-colour-knowledge-supplement/1',source_revision=a.revision,nodes=nodes,edges=edges,source_blobs=[dict(path=k,revision=a.revision,bytes=len(v),sha256=hashlib.sha256(v).hexdigest()) for k,v in blobs.items()],core_and_prior_supplements_unchanged=True,consumed_post_read_selection=True,full_standard_classification=False,physical_validation=False,new_stars=0,new_births=0)
